use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::process::{Command, Output};
use std::thread;

use velnor_actions_contract::config::ValidatedImageReference;

use super::{CACHE_CLEANUP_PATH, CLIENT, render_cache_cleanup_yml};

const MARKER: &str =
    "# Generated by Velnor Actions 0.1.37; edit .velnor/config.toml and regenerate.\n";
const SCALE_TOKEN: &str = "scale-set:velnor+ubuntu-26.04-scale-set";
const IMAGE: &str = "ghcr.io/tailrocks/velnor-job@sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
const PR_REF: &str = "refs/pull/17/merge";
const FIRST_PAGE: &str = "GET /repos/tailrocks/velnor-new/actions/caches?ref=refs%2Fpull%2F17%2Fmerge&per_page=100&page=1";

fn mock_response(stream: &mut TcpStream, status: &str, body: &str) {
    write!(
        stream,
        "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
        body.len()
    )
    .expect("The mock API could not write the response.");
}

fn run_client(script: &str, address: &str) -> Output {
    Command::new("python3")
        .arg("-c")
        .arg(script)
        .env("GH_REPO", "tailrocks/velnor-new")
        .env("GH_API_URL", address)
        .env("GH_TOKEN", "test-token")
        .env("PR_REF", PR_REF)
        .output()
        .expect("The test could not run the cleanup client.")
}

fn serve(listener: &TcpListener, exchanges: &[(&str, &str, &str)]) -> Vec<String> {
    let mut requests = Vec::new();
    for (expected_path, status, body) in exchanges {
        let (mut stream, _) = listener
            .accept()
            .expect("The mock API could not accept the request.");
        let mut request = Vec::new();
        let mut byte = [0_u8; 1];
        while !request.ends_with(b"\r\n\r\n") {
            stream
                .read_exact(&mut byte)
                .expect("The mock API could not read the request headers.");
            request.push(byte[0]);
        }
        let text = String::from_utf8(request).expect("The request headers are not UTF-8.");
        let first = text
            .lines()
            .next()
            .expect("The test request has no request line.")
            .split_whitespace()
            .take(2)
            .collect::<Vec<_>>()
            .join(" ");
        assert_eq!(first, *expected_path);
        assert!(text.contains("Authorization: Bearer test-token\r\n"));
        requests.push(first);
        mock_response(&mut stream, status, body);
    }
    requests
}

fn run_single_response(status: &'static str, body: String) -> (Output, Vec<String>) {
    let listener =
        TcpListener::bind("127.0.0.1:0").expect("The test could not bind the mock API socket.");
    let address = listener
        .local_addr()
        .expect("The test could not read the mock API address.");
    let server = thread::spawn(move || {
        let exchanges = [(FIRST_PAGE, status, body.as_str())];
        serve(&listener, &exchanges)
    });
    let output = run_client(CLIENT, &format!("http://{address}"));
    let requests = server
        .join()
        .expect("The mock API thread did not complete.");
    (output, requests)
}

fn serve_short_pages(listener: &TcpListener) -> Vec<String> {
    let mut requests = Vec::new();
    for page in 1..=64 {
        let (mut stream, _) = listener
            .accept()
            .expect("The mock API could not accept the cache page request.");
        let mut request = Vec::new();
        let mut byte = [0_u8; 1];
        while !request.ends_with(b"\r\n\r\n") {
            stream
                .read_exact(&mut byte)
                .expect("The mock API could not read the request headers.");
            request.push(byte[0]);
        }
        let text = String::from_utf8(request).expect("The request headers are not UTF-8.");
        let first = text
            .lines()
            .next()
            .expect("The test request has no request line.")
            .to_owned();
        assert!(first.contains(&format!("page={page} HTTP/1.1")));
        assert!(text.contains("Authorization: Bearer test-token\r\n"));
        requests.push(first);
        let body = format!(
            r#"{{"total_count":6400,"actions_caches":[{{"id":{page},"ref":"refs/pull/17/merge"}}]}}"#
        );
        mock_response(&mut stream, "200 OK", &body);
    }
    requests
}

fn serve_large_pages(listener: &TcpListener) -> Vec<String> {
    let mut requests = Vec::new();
    for page in 1..=17 {
        let (mut stream, _) = listener
            .accept()
            .expect("The mock API could not accept the cache page request.");
        let mut request = Vec::new();
        let mut byte = [0_u8; 1];
        while !request.ends_with(b"\r\n\r\n") {
            stream
                .read_exact(&mut byte)
                .expect("The mock API could not read the request headers.");
            request.push(byte[0]);
        }
        let text = String::from_utf8(request).expect("The request headers are not UTF-8.");
        let first = text
            .lines()
            .next()
            .expect("The test request has no request line.")
            .to_owned();
        assert!(first.contains(&format!("page={page} HTTP/1.1")));
        assert!(text.contains("Authorization: Bearer test-token\r\n"));
        requests.push(first);
        let prefix = format!(
            r#"{{"total_count":17,"actions_caches":[{{"id":{page},"ref":"refs/pull/17/merge"}}],"padding":""}}"#
        );
        let stem = prefix
            .strip_suffix("\"}")
            .expect("The test response has no padding suffix.");
        let size = 1024 * 1024 - 100;
        let padding = "x".repeat(size - stem.len() - 2);
        let body = format!("{stem}{padding}\"}}");
        mock_response(&mut stream, "200 OK", &body);
    }
    requests
}

#[test]
fn hosted_workflow_keeps_close_fork_ref_and_permission_guards() {
    let file = render_cache_cleanup_yml("ubuntu-26.04", None, "0.1.37").expect("render");
    assert_eq!(file.path, CACHE_CLEANUP_PATH);
    assert!(file.bytes.starts_with(MARKER));
    assert!(file.bytes.contains("types:\n      - closed\n"));
    assert!(file.bytes.contains("runs-on: ubuntu-26.04\n"));
    assert!(
        file.bytes
            .contains("if: github.event.pull_request.head.repo.fork == false")
    );
    assert!(file.bytes.contains("permissions: {}\n"));
    assert_eq!(file.bytes.matches("actions: write").count(), 1);
    assert!(
        file.bytes
            .contains("PR_REF: refs/pull/${{ github.event.pull_request.number }}/merge")
    );
    assert!(!file.bytes.contains("actions/checkout"));
    assert!(!file.bytes.contains("gh cache"));
}

#[test]
fn scale_set_workflow_uses_selected_labels_and_container_without_hosted_fallback() {
    let image =
        ValidatedImageReference::parse(IMAGE).expect("The test image reference is not immutable.");
    let file = render_cache_cleanup_yml(SCALE_TOKEN, Some(&image), "0.1.37").expect("render");
    assert!(
        file.bytes
            .contains("runs-on: [velnor, ubuntu-26.04-scale-set]\n")
    );
    assert!(
        file.bytes
            .contains(&format!("container:\n      image: {IMAGE}\n"))
    );
    assert!(!file.bytes.contains("ubuntu-latest"));
    assert!(!file.bytes.contains("gh cache"));
}

#[test]
fn scale_set_without_image_and_hosted_with_image_fail_closed() {
    assert!(render_cache_cleanup_yml(SCALE_TOKEN, None, "0.1.37").is_err());
    let image =
        ValidatedImageReference::parse(IMAGE).expect("The test image reference is not immutable.");
    assert!(render_cache_cleanup_yml("ubuntu-26.04", Some(&image), "0.1.37").is_err());
}

